          "lead_time_weeks": {
            "type": "integer",
            "minimum": 0,
            "maximum": 9007199254740991
          },
          "base_unit_price": {
            "type": "number",
            "minimum": 0
          },
          "surcharge_per_unit": {
            "type": "number",
            "minimum": 0
          },
          "packaging_per_unit": {
            "type": "number",
            "minimum": 0
          },
          "rebate_total": {
            "type": "number",
            "minimum": 0
          }
        },
        "required": [
          "position",
          "material_number",
          "quantity",
          "unit_price",
          "lead_time_weeks"
        ],
        "additionalProperties": false
      }
    },
    "total_net": {
      "type": "number",
      "minimum": 0
    },
    "notes": {
      "type": "string",
      "maxLength": 4000
    }
  },
  "required": [
    "tender_reference",
    "decision",
    "currency",
    "discount_percent",
    "positions",
    "total_net"
  ],
  "additionalProperties": false
}
