"""The bid calculation: every number in the answer comes from here, in exact decimals.

The model decides which facts apply (which tender, revision, material, mail, condition); this module applies the
brief's arithmetic to them. It knows the rules, never the data: everything arrives in `inputs`, built at run time
from what the investigators read on the websites.

Rounding is always HALF_UP to the cent. Python's round() rounds half to even and would lose cents.
"""
import math
import re
from decimal import ROUND_DOWN, ROUND_HALF_UP, Decimal, InvalidOperation

CENT = Decimal("0.01")
ZERO = Decimal("0")


def dec(value) -> Decimal | None:
    """A Decimal from a number or a string; German "1.234,56" and plain "1234.56" both work. None stays None."""
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, Decimal):
        return value
    if isinstance(value, int):
        return Decimal(value)
    if isinstance(value, float):
        return Decimal(repr(value))
    text = re.sub(r"[^\d,.\-]", "", str(value))
    if not re.search(r"\d", text):
        return None
    if "," in text and "." in text:
        # whichever separator comes last is the decimal one
        if text.rfind(",") > text.rfind("."):
            text = text.replace(".", "").replace(",", ".")
        else:
            text = text.replace(",", "")
    elif "," in text:
        text = text.replace(".", "").replace(",", ".") if text.count(",") == 1 else text.replace(",", "")
    try:
        return Decimal(text)
    except InvalidOperation:
        return None


def money(value: Decimal) -> Decimal:
    """Rounded HALF_UP to the cent."""
    return value.quantize(CENT, rounding=ROUND_HALF_UP)


def position_key(position: str):
    """Natural order of position numbers: "2" before "10", "1.2" before "1.10"."""
    return [(0, int(part), "") if part.isdigit() else (1, 0, part) for part in re.split(r"(\d+)", str(position)) if part]


def day(value) -> str | None:
    """The calendar date (YYYY-MM-DD) of an ISO date or timestamp, or of a German date (25.01.2027)."""
    if not value:
        return None
    text = str(value).strip()
    if match := re.match(r"(\d{4})-(\d{2})-(\d{2})", text):
        return "-".join(match.groups())
    if match := re.match(r"(\d{1,2})\.(\d{1,2})\.(\d{4})", text):
        d, m, y = match.groups()
        return f"{y}-{int(m):02d}-{int(d):02d}"
    return None


def final_quantity(position: dict) -> int:
    """Rules 1, "withdrawn answers" and "units": the latest dated quantity change that was not withdrawn, else the
    tender quantity; sets are converted to pieces with the governing specification's pieces per set."""
    withdrawn = {str(number).strip() for number in position.get("withdrawn_qa_numbers") or []}
    changes = [change for change in position.get("quantity_changes") or []
               if str(change.get("qa_number", "")).strip() not in withdrawn and change.get("quantity") is not None]
    quantity = dec(position.get("tender_quantity")) or ZERO
    if changes:
        latest = max(changes, key=lambda change: str(change.get("date") or ""))
        quantity = dec(latest["quantity"])
    pieces_per_set = dec(position.get("pieces_per_set"))
    if pieces_per_set and position.get("unit_is_set"):
        quantity *= pieces_per_set
    return int(quantity)


def scale_price(price: dict, quantity: int) -> Decimal | None:
    """Rule 4 and "currency": the scale with the highest minimum quantity no greater than the quantity, per piece
    (price unit normalised), converted to EUR and rounded HALF_UP to cents."""
    scales = [(dec(scale.get("min_quantity")) or ZERO, dec(scale.get("price"))) for scale in price.get("scales") or []]
    scales = [(minimum, amount) for minimum, amount in scales if amount is not None and minimum <= quantity]
    if not scales:
        return None
    _, amount = max(scales, key=lambda scale: scale[0])
    per_piece = amount / (dec(price.get("price_unit")) or Decimal(1))
    currency = (price.get("currency") or "EUR").strip().upper()
    if currency != "EUR":
        rate = dec(price.get("eur_per_currency_unit"))
        if rate is None:
            return None
        per_piece *= rate
    return money(per_piece)


def metal_rate(index: dict | None, scenario_day: str | None) -> Decimal | None:
    """"Metal indices": the rate whose inclusive validity window contains the scenario date; a rate without a window
    applies when no windowed rate does."""
    if not index:
        return None
    rates = index.get("rates") or []
    for rate in rates:
        start, end = day(rate.get("valid_from")), day(rate.get("valid_to"))
        if (start or end) and scenario_day and (not start or start <= scenario_day) and (not end or scenario_day <= end):
            return dec(rate.get("eur_per_kg"))
    unwindowed = [rate for rate in rates if not rate.get("valid_from") and not rate.get("valid_to")]
    return dec(unwindowed[-1].get("eur_per_kg")) if unwindowed else None


def allocate(total: Decimal, weights: dict[str, Decimal], method: str = "largest_remainder") -> dict[str, Decimal]:
    """Split `total` (in cents) over the keys by weight. Every method floors each share to the cent first; the cents
    left over go by the largest remainders (ties: ascending position), all to the largest share, or all to the first
    or the last position."""
    keys = sorted(weights, key=position_key)
    weight_sum = sum(weights.values())
    if not keys or weight_sum <= 0:
        return {key: ZERO for key in keys}
    exact = {key: total * weights[key] / weight_sum for key in keys}
    shares = {key: exact[key].quantize(CENT, rounding=ROUND_DOWN) for key in keys}
    left = int((total - sum(shares.values())) / CENT)
    if method == "remainder_to_largest_share":
        receivers = [max(keys, key=lambda key: (exact[key], [-1 * k[1] for k in position_key(key)]))] * left
    elif method == "remainder_to_first":
        receivers = [keys[0]] * left
    elif method == "remainder_to_last":
        receivers = [keys[-1]] * left
    else:
        by_remainder = sorted(keys, key=lambda key: (-(exact[key] - shares[key]), position_key(key)))
        receivers = by_remainder[:left]
    for key in receivers:
        shares[key] += CENT
    return shares


def project_bonus(bands: list[dict], goods_total: Decimal) -> Decimal:
    """"Project bonus": marginal bands, each percentage applied only to its portion of the goods total, rounded
    HALF_UP once."""
    credit = ZERO
    for band in bands:
        start = dec(band.get("from_eur")) or ZERO
        end = dec(band.get("to_eur"))
        top = goods_total if end is None else min(goods_total, end)
        if top > start:
            credit += (top - start) * (dec(band.get("percent")) or ZERO) / 100
    return money(credit)


def compute(inputs: dict) -> tuple[dict, list[str]]:
    """The answer and a log of how each number came about."""
    log: list[str] = []
    reference = inputs["tender_reference"]
    scenario_day = day(inputs.get("scenario_date"))
    approval = inputs.get("discount_approval") or {}
    percent = dec(approval.get("percent")) or ZERO

    if inputs.get("decision") == "no_bid":
        conditional = dec(approval.get("min_order_value_eur")) is not None
        discount = ZERO if conditional else percent
        log.append(f"no_bid: {inputs.get('decision_reason', '')}")
        return {"tender_reference": reference, "decision": "no_bid", "currency": "EUR",
                "discount_percent": float(discount), "positions": [], "total_net": 0.0}, log

    lines = []
    for position in sorted(inputs.get("positions") or [], key=lambda p: position_key(p["position"])):
        quantity = final_quantity(position)
        base = scale_price(position.get("price") or {}, quantity) if quantity else None
        if not position.get("material_number") or not quantity or base is None:
            log.append(f"position {position['position']}: omitted (material {position.get('material_number')}, "
                       f"quantity {quantity}, base {base})")
            continue
        lines.append({**position, "quantity": quantity, "base": base})
        log.append(f"position {position['position']}: {quantity} pieces of {position['material_number']}, "
                   f"base {base} EUR")

    # "Conditional discount": the undiscounted net order value against the approval's inclusive threshold
    order_value = money(sum((line["base"] * line["quantity"] for line in lines), ZERO))
    threshold = dec(approval.get("min_order_value_eur"))
    discount = percent if threshold is None or order_value >= threshold else ZERO
    log.append(f"discount {discount} % (approved {percent} %, threshold {threshold}, order value {order_value})")
    rate = 1 - discount / 100

    metal = metal_rate(inputs.get("metal_index"), scenario_day)
    log.append(f"metal rate {metal} EUR/kg on {scenario_day}")

    # "Shared setup": one fee per pool, split by quantity x allocation mass
    pool_share: dict[str, Decimal] = {}
    for pool in inputs.get("setup_pools") or []:
        members = {line["position"]: line["quantity"] * (dec(line.get("allocation_mass_kg")) or ZERO)
                   for line in lines if line.get("setup_pool_key") == pool.get("key")}
        shares = allocate(dec(pool.get("fee_eur")) or ZERO, members, pool.get("allocation") or "largest_remainder")
        pool_share.update(shares)
        log.append(f"setup pool {pool.get('key')}: {dict((k, str(v)) for k, v in shares.items())}")

    # "Project bonus": on the eligible undiscounted goods total, split by largest remainder
    bonus_share: dict[str, Decimal] = {}
    bonus = inputs.get("project_bonus") or {}
    eligible = {line["position"]: line["base"] * line["quantity"] for line in lines if line.get("project_bonus_member")}
    if bonus.get("bands") and eligible:
        credit = project_bonus(bonus["bands"], sum(eligible.values(), ZERO))
        bonus_share = allocate(credit, eligible)
        log.append(f"project bonus {credit} EUR: {dict((k, str(v)) for k, v in bonus_share.items())}")

    # "Shared stock" and "delivery": demand pooled per material
    demand: dict[str, int] = {}
    for line in lines:
        demand[line["material_number"]] = demand.get(line["material_number"], 0) + line["quantity"]

    positions, total = [], ZERO
    for line in lines:
        key, quantity = line["position"], line["quantity"]
        scope = line.get("discount_scope") or "base_only"
        base = line["base"]
        mass = (dec(line.get("surcharge_mass_kg")) or ZERO) * (metal or ZERO)
        setup = (dec(line.get("setup_fee")) or ZERO) + pool_share.get(key, ZERO)
        per_carton = dec(line.get("carton_tariff_eur"))
        carton_size = dec(line.get("pieces_per_carton"))
        packaging = (Decimal(math.ceil(quantity / carton_size)) * per_carton
                     if per_carton is not None and carton_size else ZERO)
        credit = bonus_share.get(key, ZERO)

        # "Final price": from unrounded parts, rounded once
        discounted_base = base * rate if scope in ("base_only", "base_and_surcharge") else base
        discounted_mass = mass * rate if scope == "base_and_surcharge" else mass
        unit_price = money(discounted_base + discounted_mass + (setup + packaging - credit) / quantity)
        total += quantity * unit_price

        answer = {"position": str(key), "material_number": line["material_number"], "quantity": quantity,
                  "unit_price": float(unit_price), "lead_time_weeks": lead_time(line, demand)}
        answer["base_unit_price"] = float(base)
        if metal is not None or line.get("surcharge_mass_kg") is None or line.get("setup_fee") is not None:
            answer["surcharge_per_unit"] = float(money(mass + setup / quantity))
        if per_carton is not None or line.get("packaging_known_zero"):
            answer["packaging_per_unit"] = float(money(packaging / quantity))
        if bonus.get("bands") or line.get("project_bonus_member") is False:
            answer["rebate_total"] = float(credit)
        positions.append(answer)
        log.append(f"position {key}: unit {unit_price} = base {base} x {rate} ({scope}) + mass {mass} + "
                   f"(setup {setup} + packaging {packaging} - bonus {credit}) / {quantity}; "
                   f"lead {answer['lead_time_weeks']} weeks")

    return {"tender_reference": reference, "decision": "bid", "currency": "EUR",
            "discount_percent": float(discount), "positions": positions,
            "total_net": float(money(total))}, log


def lead_time(line: dict, demand: dict[str, int]) -> int:
    """Rule 6, "shared stock" and "delivery": a matching commitment within its ceiling, else stock delivery when stock
    covers the whole pooled demand for the material, else production."""
    pooled = demand[line["material_number"]]
    commitment = line.get("delivery_commitment") or {}
    ceiling = dec(commitment.get("ceiling_pieces"))
    if (commitment.get("lead_time_weeks") is not None and commitment.get("material_number") == line["material_number"]
            and (ceiling is None or pooled <= ceiling)):
        return int(commitment["lead_time_weeks"])
    stock = dec(line.get("stock"))
    if stock is not None and stock >= pooled and line.get("stock_lead_time_weeks") is not None:
        return int(line["stock_lead_time_weeks"])
    weeks = line.get("production_lead_time_weeks")
    if weeks is None:
        weeks = line.get("stock_lead_time_weeks") or 0
    return int(weeks)


def german(value, decimals: int = 2) -> str:
    """A number as the German forms want it: 1234.5 -> "1.234,50"."""
    amount = Decimal(str(value)).quantize(Decimal(1).scaleb(-decimals), rounding=ROUND_HALF_UP)
    whole, _, fraction = f"{amount:,.{decimals}f}".partition(".")
    whole = whole.replace(",", ".")
    return f"{whole},{fraction}" if decimals else whole

"""The browser side: a compact text view of whatever page is open, and actions on its numbered elements.

Nothing here knows the websites. The view renders any page the same way: text in reading order, tables as rows,
frames after the page, and every element the model can act on as [n kind "label"]. Code helps where the brief allows
it (logging in with the run's credentials, retrying error pages, reading a document the model picked); the model
chooses where to go and what to do.
"""
import asyncio
import base64
import io
import re
import tempfile
import time
import zipfile
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin, urlparse

MAX_VIEW = 16000  # characters of the page shown at once; more() pages through the rest
MAX_DOCUMENT = 40000

# Renders the document of one frame and numbers what can be acted on, starting at `start`.
RENDER = r"""
(start) => {
  let n = start, line = '', inCell = 0;
  const lines = [];
  const flush = () => { const t = line.replace(/[ \t ]+/g, ' ').trim(); if (t && t !== lines[lines.length - 1]) lines.push(t); line = ''; };
  const brk = () => { if (inCell) line += ' '; else flush(); };
  const clip = (s, k) => { s = String(s || '').replace(/\s+/g, ' ').trim(); return s.length > k ? s.slice(0, k) + '…' : s; };
  const q = (s) => JSON.stringify(s);
  const SKIP = new Set(['SCRIPT', 'STYLE', 'NOSCRIPT', 'TEMPLATE', 'HEAD', 'META', 'LINK', 'svg', 'SVG', 'OPTION']);
  const ROLES = new Set(['button', 'link', 'tab', 'menuitem', 'menuitemcheckbox', 'menuitemradio', 'checkbox', 'radio',
    'option', 'switch', 'treeitem', 'combobox', 'textbox', 'searchbox']);
  const CONTROLS = 'a[href],button,input:not([type=hidden]),select,textarea,[role=button],[role=link],[onclick]';
  document.querySelectorAll('[data-agent-ref]').forEach((e) => e.removeAttribute('data-agent-ref'));

  const labelOf = (el) => {
    let s = el.getAttribute('aria-label') || '';
    if (!s && el.labels && el.labels.length) s = [...el.labels].map((l) => l.innerText).join(' ');
    const by = el.getAttribute('aria-labelledby');
    if (!s && by) s = by.split(/\s+/).map((i) => (document.getElementById(i) || {}).innerText || '').join(' ');
    return clip(s || el.getAttribute('title') || el.getAttribute('placeholder') || el.name || '', 80);
  };
  const pointer = (el) => {
    const parent = el.parentElement;
    return getComputedStyle(el).cursor === 'pointer' && !(parent && getComputedStyle(parent).cursor === 'pointer')
      && clip(el.innerText, 300).length < 200 && !el.querySelector(CONTROLS) && !(el.tagName === 'LABEL' && el.control);
  };
  const interactive = (el) => {
    const t = el.tagName;
    if (t === 'A') return el.hasAttribute('href') || el.hasAttribute('onclick');
    if (t === 'BUTTON' || t === 'SELECT' || t === 'TEXTAREA' || t === 'SUMMARY') return true;
    if (t === 'INPUT') return el.type !== 'hidden';
    if (el.querySelector(CONTROLS)) return false;  // a container: its controls are listed instead
    const role = el.getAttribute('role');
    if (role && ROLES.has(role)) return true;
    if (el.hasAttribute('onclick') || (el.hasAttribute('tabindex') && el.tabIndex >= 0)) return true;
    if (el.isContentEditable && !(el.parentElement && el.parentElement.isContentEditable)) return true;
    return pointer(el);
  };
  const render = (el) => {
    const t = el.tagName, id = n++;
    el.setAttribute('data-agent-ref', id);
    const off = el.disabled || el.getAttribute('aria-disabled') === 'true' ? ' disabled' : '';
    if (t === 'INPUT' || t === 'TEXTAREA') {
      const type = t === 'TEXTAREA' ? 'textarea' : (el.type || 'text');
      if (type === 'checkbox' || type === 'radio') return `[${id} ${type} ${q(labelOf(el))}${el.checked ? ' checked' : ''}${off}]`;
      if (['submit', 'button', 'reset', 'image'].includes(type)) return `[${id} button ${q(clip(el.value || labelOf(el) || type, 80))}${off}]`;
      if (type === 'file') return `[${id} file-input ${q(labelOf(el))}${off}]`;
      const kind = type === 'text' ? 'input' : `${type}-input`;
      return `[${id} ${kind} ${q(labelOf(el))} value=${q(clip(el.value, 120))}${el.readOnly ? ' readonly' : ''}${el.required ? ' required' : ''}${off}]`;
    }
    if (t === 'SELECT') {
      const opts = [...el.options];
      const chosen = opts.filter((o) => o.selected).map((o) => clip(o.text, 60)).join(', ');
      const list = opts.slice(0, 40).map((o) => q(clip(o.text, 60))).join(' | ');
      return `[${id} select ${q(labelOf(el))} selected=${q(chosen)} options: ${list}${opts.length > 40 ? ` | … ${opts.length - 40} more` : ''}${off}]`;
    }
    const role = el.getAttribute('role') || (t === 'A' ? 'link' : (t === 'BUTTON' || t === 'SUMMARY') ? 'button' : 'clickable');
    const text = clip(el.innerText || el.getAttribute('aria-label') || el.getAttribute('title') || el.value || '', 100);
    let to = '';
    const href = t === 'A' ? el.getAttribute('href') : '';
    if (href && !href.startsWith('javascript') && href !== '#') {
      const u = new URL(el.href, location.href);
      to = ' → ' + (u.origin === location.origin ? u.pathname + u.search + u.hash : u.href);
    }
    const state = ['aria-selected', 'aria-checked', 'aria-expanded', 'aria-pressed', 'aria-current']
      .filter((a) => el.getAttribute(a) && el.getAttribute(a) !== 'false').map((a) => ' ' + a.slice(5)).join('');
    return `[${id} ${role} ${q(text)}${to}${state}${off}]`;
  };
  const walk = (node) => {
    if (node.nodeType === Node.TEXT_NODE) { line += node.textContent; return; }
    if (node.nodeType !== Node.ELEMENT_NODE) return;
    const el = node, t = el.tagName;
    if (SKIP.has(t)) return;
    const style = getComputedStyle(el);
    if (style.display === 'none' || style.visibility === 'hidden') return;
    if (t === 'IFRAME' || t === 'FRAME' || t === 'OBJECT' || t === 'EMBED') {
      brk(); line += `[frame ${q(el.title || el.name || '')} src=${q(clip(el.getAttribute('src') || el.getAttribute('data') || '', 160))}]`; brk();
      return;
    }
    if (t === 'BR' || t === 'HR') { brk(); return; }
    if (interactive(el)) { line += ' ' + render(el) + ' '; return; }
    if (t === 'TR') {
      flush(); inCell++;
      for (const cell of el.children) { walk(cell); line += ' |'; }
      inCell--; line = '| ' + line; flush();
      return;
    }
    const role = el.getAttribute('role');
    const block = !style.display.startsWith('inline') || /^H[1-6]$/.test(t) || t === 'LI';
    if (block) brk();
    if (/^H[1-6]$/.test(t) && !inCell) line += '#'.repeat(+t[1]) + ' ';
    if (t === 'LI' && !inCell) line += '- ';
    if (t === 'DIALOG' || role === 'dialog' || role === 'alertdialog' || el.getAttribute('aria-modal') === 'true') { line += '[dialog] '; }
    if (role === 'alert' || role === 'status') line += '[notice] ';
    for (const child of el.childNodes) walk(child);
    if (el.shadowRoot) for (const child of el.shadowRoot.childNodes) walk(child);
    if (block) brk();
  };
  if (document.body) walk(document.body);
  flush();
  return { text: lines.join('\n'), next: n };
}
"""

# Marks the visible login form's user and password fields, for login().
MARK_LOGIN = r"""
() => {
  const visible = (e) => { const r = e.getBoundingClientRect(), s = getComputedStyle(e); return r.width > 0 && r.height > 0 && s.visibility !== 'hidden' && s.display !== 'none'; };
  document.querySelectorAll('[data-agent-login]').forEach((e) => e.removeAttribute('data-agent-login'));
  const password = [...document.querySelectorAll('input[type=password]')].find(visible);
  if (!password) return false;
  const fields = [...(password.form || document).querySelectorAll('input')].filter((e) => visible(e)
    && !['password', 'hidden', 'checkbox', 'radio', 'submit', 'button', 'image', 'reset'].includes(e.type));
  const before = fields.filter((e) => e.compareDocumentPosition(password) & Node.DOCUMENT_POSITION_FOLLOWING);
  const user = before.length ? before[before.length - 1] : fields[0];
  password.setAttribute('data-agent-login', 'password');
  if (user) user.setAttribute('data-agent-login', 'user');
  return true;
}
"""

# Fetches a URL inside the page, with its cookies and through the browser's own network path.
FETCH = r"""
async (url) => {
  const r = await fetch(url, { credentials: 'include' });
  const bytes = new Uint8Array(await r.arrayBuffer());
  let bin = '';
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
  return { status: r.status, type: r.headers.get('content-type') || '', name: r.headers.get('content-disposition') || '',
           url: r.url, data: btoa(bin) };
}
"""


def short(text, limit=300) -> str:
    text = re.sub(r"\s+", " ", str(text)).strip()
    return text if len(text) <= limit else text[:limit] + "…"


class Site:
    """One website, driven in its own browser: the active tab, its numbered elements, dialogs, new tabs, downloads."""

    def __init__(self, access: dict, context, page, log=print):
        self.id = access.get("siteId") or urlparse(access["url"]).hostname
        self.url = access["url"]
        self.credentials = access.get("credentials") or {}
        self.context, self.page, self.log = context, page, log
        self.refs: dict[int, object] = {}  # element number -> the frame it is in
        self.events: list[str] = []  # dialogs, tabs and downloads since the last view
        self.downloads: list[Path] = []
        self.full_view, self.shown = "", 0
        self.lock = asyncio.Lock()  # one agent at a time drives this browser
        context.on("page", self._new_tab)
        self._watch(page)

    # --- events -------------------------------------------------------------------------------------------------

    def _watch(self, page):
        page.on("dialog", self._dialog)
        page.on("download", self._download)

    def _new_tab(self, page):
        self._watch(page)
        self.page = page
        self.events.append("A new tab opened and is now the active tab.")

    async def _dialog(self, dialog):
        # Browser dialogs block the page until answered. The agents only trigger them on purpose (the final
        # confirmation of a bid is one), so they are accepted and reported in the next view.
        self.events.append(f"A browser {dialog.type} dialog said {short(dialog.message)!r}; it was accepted.")
        try:
            await dialog.accept()
        except Exception:
            pass

    async def _download(self, download):
        target = Path(tempfile.mkdtemp()) / (download.suggested_filename or "download")
        try:
            await download.save_as(target)
        except Exception as error:
            self.events.append(f"A download failed: {short(error)}")
            return
        self.downloads.append(target)
        self.events.append(f"Downloaded {target.name!r}: read it with read_document(download={len(self.downloads)}).")

    async def _active(self):
        if self.page.is_closed():
            open_pages = [page for page in self.context.pages if not page.is_closed()]
            self.page = open_pages[-1] if open_pages else await self.context.new_page()
            self.events.append("The tab closed; switched to the previous tab.")
        return self.page

    async def _settle(self):
        page = await self._active()
        for state, timeout in (("domcontentloaded", 10000), ("networkidle", 1500)):
            try:
                await page.wait_for_load_state(state, timeout=timeout)
            except Exception:
                pass
        await asyncio.sleep(0.2)

    # --- the view -----------------------------------------------------------------------------------------------

    async def view(self) -> str:
        """The page as text, from the top; long pages are cut, more() shows the rest."""
        page = await self._active()
        self.refs, number, parts = {}, 1, []
        for frame in page.frames:
            try:
                rendered = await frame.evaluate(RENDER, number)
            except Exception:
                continue
            for ref in range(number, rendered["next"]):
                self.refs[ref] = frame
            number = rendered["next"]
            if frame is page.main_frame:
                parts.insert(0, rendered["text"])
            elif rendered["text"].strip():
                parts.append(f"--- inside frame {frame.name or ''} {short(frame.url, 120)} ---\n{rendered['text']}")
        try:
            title = await page.title()
        except Exception:
            title = ""
        tabs = [p for p in self.context.pages if not p.is_closed()]
        header = f"URL: {page.url}\nTitle: {title}\n"
        if len(tabs) > 1:
            header += "Tabs: " + " | ".join(f"{i}{' (active)' if p is page else ''}: {short(p.url, 80)}"
                                            for i, p in enumerate(tabs)) + "\n"
        if self.events:
            header += "".join(f"Event: {event}\n" for event in self.events)
            self.events = []
        self.full_view = header + "\n" + "\n\n".join(parts)
        return self._part(0)

    def _part(self, start: int) -> str:
        end = start + MAX_VIEW
        self.shown = end
        text = self.full_view[start:end]
        if start:
            text = f"[page text from character {start}]\n" + text
        if end < len(self.full_view):
            text += f"\n[… {len(self.full_view) - end} more characters: more() shows them, find(text) searches them]"
        return text

    async def more(self) -> str:
        if self.shown >= len(self.full_view):
            return "That was the end of the page."
        return self._part(self.shown)

    async def find(self, text: str) -> str:
        """Lines of the current page containing `text` (case-insensitive), with the line after each."""
        lines = self.full_view.splitlines()
        hits = [i for i, line in enumerate(lines) if text.lower() in line.lower()]
        if not hits:
            return f"{text!r} is not on the current page (as of the last view)."
        return "\n".join("\n".join(lines[i:i + 2]) for i in hits[:40])

    # --- actions ------------------------------------------------------------------------------------------------

    def _element(self, ref):
        frame = self.refs.get(int(ref))
        if frame is None:
            raise LookupError(f"There is no element [{ref}] on the page as last viewed; look at the current view.")
        return frame.locator(f'[data-agent-ref="{int(ref)}"]').first

    async def click(self, ref) -> str:
        element = self._element(ref)
        try:
            await element.click(timeout=5000)
        except Exception as error:
            try:  # covered by an overlay or off screen: a DOM click still reaches the element's handler
                await element.evaluate("(e) => e.click()", timeout=3000)
            except Exception:
                return f"Could not click [{ref}]: {short(error)}\n\n" + await self.view()
        await self._settle()
        return await self.view()

    async def fill(self, fields: list[dict]) -> str:
        """Several inputs at once: text is typed, selects choose the option by label or value, checkboxes take
        true/false."""
        problems = []
        for field in fields:
            ref, value = field.get("ref"), field.get("value")
            try:
                element = self._element(ref)
                kind = await element.evaluate("(e) => e.tagName === 'SELECT' ? 'select' : (e.type || '').toLowerCase()")
                if kind == "select":
                    try:
                        await element.select_option(label=str(value), timeout=3000)
                    except Exception:
                        await element.select_option(value=str(value), timeout=3000)
                elif kind in ("checkbox", "radio"):
                    want = value if isinstance(value, bool) else str(value).lower() in ("true", "1", "yes", "ja", "on")
                    try:
                        await element.set_checked(want, timeout=3000)
                    except Exception:
                        await element.set_checked(want, force=True, timeout=3000)
                else:
                    await element.fill(str(value), timeout=4000)
            except Exception as error:
                problems.append(f"[{ref}]: {short(error, 200)}")
        await self._settle()
        report = "Filled." if not problems else "Problems: " + "; ".join(problems)
        return report + "\n\n" + await self.view()

    async def type(self, ref, text: str, enter: bool = False) -> str:
        element = self._element(ref)
        try:
            await element.fill(text, timeout=4000)
        except Exception:
            await element.click(timeout=3000)
            await (await self._active()).keyboard.type(text)
        if enter:
            await element.press("Enter")
        await self._settle()
        return await self.view()

    async def press(self, key: str, ref=None) -> str:
        if ref is not None:
            await self._element(ref).press(key, timeout=4000)
        else:
            await (await self._active()).keyboard.press(key)
        await self._settle()
        return await self.view()

    async def goto(self, url: str) -> str:
        page = await self._active()
        target = urljoin(page.url if page.url.startswith("http") else self.url, url)
        for attempt in range(3):  # flaky error pages: retry a server error a few times
            try:
                response = await page.goto(target, wait_until="domcontentloaded", timeout=20000)
                if response is None or response.status < 500:
                    break
                self.log(f"[{self.id}] HTTP {response.status} on {target}, retrying")
            except Exception as error:
                self.log(f"[{self.id}] {short(error, 120)}, retrying")
            await asyncio.sleep(1.5 * (attempt + 1))
        await self._settle()
        return await self.view()

    async def reload(self) -> str:
        page = await self._active()
        try:
            await page.reload(wait_until="domcontentloaded", timeout=20000)
        except Exception:
            pass
        await self._settle()
        return await self.view()

    async def back(self) -> str:
        page = await self._active()
        try:
            await page.go_back(wait_until="domcontentloaded", timeout=15000)
        except Exception:
            pass
        await self._settle()
        return await self.view()

    async def switch_tab(self, index: int) -> str:
        tabs = [p for p in self.context.pages if not p.is_closed()]
        if not 0 <= int(index) < len(tabs):
            return f"There is no tab {index}; there are {len(tabs)}."
        self.page = tabs[int(index)]
        await self.page.bring_to_front()
        return await self.view()

    async def login(self) -> str:
        """Fills this website's username and password into the visible login form and submits it."""
        page = await self._active()
        for frame in page.frames:
            try:
                found = await frame.evaluate(MARK_LOGIN)
            except Exception:
                continue
            if not found:
                continue
            user = frame.locator('[data-agent-login="user"]')
            if await user.count():
                await user.fill(str(self.credentials.get("username", "")))
            password = frame.locator('[data-agent-login="password"]')
            await password.fill(str(self.credentials.get("password", "")))
            await password.press("Enter")
            await self._settle()
            return "Submitted the login form.\n\n" + await self.view()
        return "There is no login form (password field) on this page.\n\n" + await self.view()

    async def wait(self, seconds: float) -> str:
        await asyncio.sleep(max(0.0, min(float(seconds), 30.0)))
        return await self.view()

    # --- documents ----------------------------------------------------------------------------------------------

    async def read_document(self, ref=None, url: str | None = None, download: int | None = None) -> str:
        """The text of a document the model picked: a linked file, a frame's source, or a download."""
        if download:
            path = self.downloads[int(download) - 1]
            return f"Document {path.name}:\n" + extract(path.read_bytes(), path.name)
        page = await self._active()
        frame = page.main_frame
        if ref is not None:
            element = self._element(ref)
            frame = self.refs[int(ref)]
            url = await element.evaluate("(e) => e.href || e.src || e.data || e.getAttribute('href') || ''")
            if not url or url.startswith("javascript"):
                # a button that starts a download: click it and read what arrives
                before = len(self.downloads)
                await self.click(ref)
                for _ in range(20):
                    if len(self.downloads) > before:
                        return await self.read_document(download=len(self.downloads))
                    await asyncio.sleep(0.5)
                return "The element has no link and clicking it downloaded nothing.\n\n" + await self.view()
        if not url:
            return "Give the element number, a url, or a download number."
        url = urljoin(frame.url, url)
        try:
            fetched = await frame.evaluate(FETCH, url)
        except Exception:
            fetched = await page.main_frame.evaluate(FETCH, url)
        data = base64.b64decode(fetched["data"])
        name = re.sub(r'.*filename\*?=(?:UTF-8\'\')?"?([^";]+)"?.*', r"\1", fetched["name"]) or url
        return f"Document {short(name, 120)} (HTTP {fetched['status']}, {fetched['type']}):\n" + extract(data, name, fetched["type"])


def extract(data: bytes, name: str = "", content_type: str = "") -> str:
    """Readable text from a PDF, a ZIP (each file inside), a Word file, HTML or plain text."""
    text = _extract(data, name.lower(), content_type.lower(), depth=0)
    return text if len(text) <= MAX_DOCUMENT else text[:MAX_DOCUMENT] + f"\n[… {len(text) - MAX_DOCUMENT} more characters]"


def _extract(data: bytes, name: str, content_type: str, depth: int) -> str:
    if data[:4] == b"%PDF":
        from pypdf import PdfReader
        reader = PdfReader(io.BytesIO(data))
        return "\n".join(f"--- page {i} ---\n{page.extract_text() or ''}" for i, page in enumerate(reader.pages, 1))
    if data[:2] == b"PK":
        archive = zipfile.ZipFile(io.BytesIO(data))
        names = archive.namelist()
        if "word/document.xml" in names:
            xml = archive.read("word/document.xml").decode("utf-8", "replace")
            return _strip_xml(xml.replace("</w:p>", "\n").replace("</w:tc>", " | "))
        if depth > 1:
            return f"(archive with {len(names)} files)"
        parts = [f"Archive with {len(names)} files: {', '.join(names)}"]
        for member in names:
            if not member.endswith("/"):
                parts.append(f"=== {member} ===\n" + _extract(archive.read(member), member.lower(), "", depth + 1))
        return "\n".join(parts)
    for encoding in ("utf-8", "cp1252"):
        try:
            text = data.decode(encoding)
            break
        except UnicodeDecodeError:
            continue
    else:
        text = data.decode("utf-8", "replace")
    if "html" in content_type or name.endswith((".html", ".htm")) or re.search(r"<(html|body|table|div)\b", text[:2000], re.I):
        return html_text(text)
    if name.endswith(".xml") or text.lstrip().startswith("<?xml"):
        return _strip_xml(text)
    return text


def _strip_xml(xml: str) -> str:
    return re.sub(r"[ \t]+", " ", re.sub(r"<[^>]+>", " ", xml)).strip()


class _Text(HTMLParser):
    BLOCK = {"p", "div", "br", "li", "h1", "h2", "h3", "h4", "h5", "h6", "section", "article", "table", "ul", "ol"}

    def __init__(self):
        super().__init__()
        self.parts, self.skip = [], 0

    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style"):
            self.skip += 1
        elif tag == "tr":
            self.parts.append("\n| ")
        elif tag in ("td", "th"):
            pass
        elif tag in self.BLOCK:
            self.parts.append("\n")

    def handle_endtag(self, tag):
        if tag in ("script", "style"):
            self.skip = max(0, self.skip - 1)
        elif tag in ("td", "th"):
            self.parts.append(" | ")

    def handle_data(self, data):
        if not self.skip:
            self.parts.append(data)


def html_text(html: str) -> str:
    parser = _Text()
    parser.feed(html)
    text = "".join(parser.parts)
    return "\n".join(re.sub(r"[ \t ]+", " ", line).strip() for line in text.splitlines() if line.strip())


def toolbox(site: Site) -> list[tuple[dict, object]]:
    """The browser tools every agent gets, as (OpenAI tool schema, coroutine) pairs."""
    ref = {"type": "integer", "description": "The element's number in the page view, e.g. 12 for [12 button ...]"}
    return [
        (_tool("view", "Show the current page again (it may have changed by itself).", {}), site.view),
        (_tool("more", "Show the next part of a long page.", {}), site.more),
        (_tool("find", "Search the current page's full text for a word or number; returns the matching lines.",
               {"text": {"type": "string"}}, ["text"]), site.find),
        (_tool("click", "Click an element: a link, button, tab, row, checkbox, ...", {"ref": ref}, ["ref"]), site.click),
        (_tool("fill", "Enter values into several form fields at once. Text inputs get the text, selects the option "
                       "label, checkboxes and radios true or false. Does not submit.",
               {"fields": {"type": "array", "items": {"type": "object", "properties": {
                   "ref": ref, "value": {"type": ["string", "number", "boolean"]}}, "required": ["ref", "value"]}}},
               ["fields"]), site.fill),
        (_tool("type", "Type text into one input, optionally pressing Enter afterwards (to search, for example).",
               {"ref": ref, "text": {"type": "string"}, "enter": {"type": "boolean"}}, ["ref", "text"]), site.type),
        (_tool("press", "Press a key (Enter, Escape, Tab, F4, ArrowDown, ...), on an element or the page.",
               {"key": {"type": "string"}, "ref": ref}, ["key"]), site.press),
        (_tool("goto", "Open a URL or a path on this website.", {"url": {"type": "string"}}, ["url"]), site.goto),
        (_tool("reload", "Reload the page, e.g. after an error page.", {}), site.reload),
        (_tool("back", "Browser back. Never use it inside a multi-step form: it clears the later steps.", {}), site.back),
        (_tool("switch_tab", "Make another open tab the active one (numbers as in the Tabs line).",
               {"index": {"type": "integer"}}, ["index"]), site.switch_tab),
        (_tool("login", "Log in: fills this website's username and password into the visible login form and submits "
                        "it. Use it whenever a login page appears, including after a session expired.", {}), site.login),
        (_tool("read_document", "Read a document as text: a link to a file (PDF, ZIP, Word, HTML, ...), a frame "
                                "whose content is not shown, or a downloaded file. Give the element number, a url, "
                                "or the download number.",
               {"ref": ref, "url": {"type": "string"}, "download": {"type": "integer"}}), site.read_document),
        (_tool("wait", "Wait some seconds (at most 30), then show the page.", {"seconds": {"type": "number"}},
               ["seconds"]), site.wait),
    ]


def _tool(name: str, description: str, properties: dict, required: list[str] | None = None) -> dict:
    return {"type": "function", "function": {"name": name, "description": description, "parameters": {
        "type": "object", "properties": properties, "required": required or []}}}


def now() -> float:
    return time.time()

"""The model side: calls to the hosted Qwen with retries, and the tool loop every agent runs.

An agent is a system prompt, a task and a set of tools. The model picks a tool, the code runs it and returns what
happened, until the model calls finish() or its time is up. Old page views are trimmed from the history, so a long
investigation stays small and fast.
"""
import asyncio
import json
import os
import time

from openai import APIConnectionError, APIStatusError, APITimeoutError, AsyncOpenAI

MODEL = os.environ.get("AGENT_MODEL", "qwen3.8-flash-next")
KEEP_FULL = 2  # the latest tool results shown in full; older ones are cut to their first lines
_client: AsyncOpenAI | None = None


def client() -> AsyncOpenAI:
    global _client
    if _client is None:
        # a cold model can take minutes to answer its first call
        _client = AsyncOpenAI(base_url=os.environ["QWEN_BASE_URL"], api_key=os.environ["QWEN_API_KEY"],
                              timeout=300, max_retries=1)
    return _client


async def chat(messages: list[dict], tools: list[dict] | None = None, **options):
    """One chat completion, retried on server errors, rate limits and lost connections."""
    request = {"model": MODEL, "messages": messages, "temperature": 0.2, **options}
    if tools:
        request["tools"] = tools
    for attempt in range(6):
        try:
            return await client().chat.completions.create(**request)
        except APIStatusError as error:
            if error.status_code < 500 and error.status_code != 429:
                raise
            print(f"[model] HTTP {error.status_code}, retrying", flush=True)
        except (APIConnectionError, APITimeoutError) as error:
            print(f"[model] {type(error).__name__}, retrying", flush=True)
        await asyncio.sleep(min(20, 2 ** attempt))
    raise RuntimeError("The model did not answer after several attempts")


def tool(name: str, description: str, properties: dict, required: list[str] | None = None) -> dict:
    """An OpenAI tool schema."""
    return {"type": "function", "function": {"name": name, "description": description, "parameters": {
        "type": "object", "properties": properties, "required": required or []}}}


class Agent:
    """A model with tools, working on one task until it calls finish() or its deadline passes."""

    def __init__(self, name: str, system: str, tools: list[tuple[dict, object]], deadline: float,
                 finish: dict | None = None):
        self.name, self.system, self.deadline = name, system, deadline
        self.schemas = [schema for schema, _ in tools]
        self.functions = {schema["function"]["name"]: function for schema, function in tools}
        finish = finish or {"summary": {"type": "string", "description": "What you found or did"}}
        self.schemas.append(tool("finish", "Call this when your task is done.", finish, list(finish)))
        self.result: dict | None = None
        self.steps = 0

    async def run(self, task: str, max_steps: int = 120) -> dict | None:
        messages = [{"role": "system", "content": self.system}, {"role": "user", "content": task}]
        idle, warned = 0, False
        while self.steps < max_steps and self.result is None:
            if time.time() > self.deadline:
                if warned:
                    print(f"[{self.name}] out of time", flush=True)
                    break
                warned = True
                messages.append({"role": "user", "content": "Time is up. Save anything important you have not "
                                                            "saved yet in this turn, then call finish."})
            self.steps += 1
            reply = await chat(trimmed(messages), self.schemas)
            message = reply.choices[0].message
            calls = message.tool_calls or []
            messages.append({"role": "assistant", "content": message.content or "",
                             **({"tool_calls": [call.model_dump() for call in calls]} if calls else {})})
            if message.content and message.content.strip():
                print(f"[{self.name}] says: {message.content.strip()[:300]}", flush=True)
            if not calls:
                idle += 1
                if idle >= 3:
                    break
                messages.append({"role": "user", "content": "Continue by calling a tool, or call finish if "
                                                            "your task is done."})
                continue
            idle = 0
            for call in calls:
                messages.append({"role": "tool", "tool_call_id": call.id,
                                 "content": await self._call(call.function.name, call.function.arguments)})
        return self.result

    async def _call(self, name: str, arguments: str) -> str:
        try:
            args = json.loads(arguments or "{}")
        except json.JSONDecodeError as error:
            return f"Your arguments were not valid JSON ({error}); call the tool again."
        shown = json.dumps(args, ensure_ascii=False)
        print(f"[{self.name}] {name}({shown[:200]})", flush=True)
        if name == "finish":
            self.result = args
            return "Finished."
        function = self.functions.get(name)
        if function is None:
            return f"There is no tool {name!r}."
        try:
            return str(await function(**args))
        except TypeError as error:
            return f"Wrong arguments for {name}: {error}"
        except Exception as error:
            print(f"[{self.name}] {name} failed: {type(error).__name__}: {str(error)[:200]}", flush=True)
            return f"{name} failed: {type(error).__name__}: {str(error)[:500]}"


def trimmed(messages: list[dict]) -> list[dict]:
    """The history with older tool results cut short: the model only needs the latest page views in full."""
    tool_indices = [i for i, message in enumerate(messages) if message["role"] == "tool"]
    old = set(tool_indices[:-KEEP_FULL])
    result = []
    for i, message in enumerate(messages):
        if i in old and len(message["content"]) > 600:
            message = {**message, "content": message["content"][:300] + "\n[… older output trimmed]"}
        result.append(message)
    return result

